function pipe() {
  var fns = Array.prototype.slice.call(arguments);
  return function (x) {
    return fns.reduce(function (value, fn) {
      return fn(value);
    }, x);
  };
}

function trim(s) {
  return s.trim();
}

function lower(s) {
  return s.toLowerCase();
}

function hyphenate(s) {
  return s.split(" ").join("-");
}

var slugify = pipe(trim, lower, hyphenate);
console.log(slugify("  Hello World  "));
